    public static final int[] P2_CRACKS = {8, 18, 26, 33, 41, 49, 57, 64, 70};
    public static final int P2_BURST = 77;

    /** The scene clock, in ticks since the attack state changed, between ticks; -1 if the change was not seen. */
    public float sceneClock(float partialTick) {
        return sceneSeen ? tickCount - sceneAt + partialTick : -1.0F;
    }

