    /**
     * Ticks until he meets the floor under him, falling as vanilla falls him:
     * moved by the current speed, then gravity, then drag. 99 when there is
     * nothing under him within reach.
     */
    private int ticksToGround() {
        Vec3 from = position();
        net.minecraft.world.phys.BlockHitResult hit = level().clip(
                new net.minecraft.world.level.ClipContext(from, from.add(0.0D, -48.0D, 0.0D),
                        net.minecraft.world.level.ClipContext.Block.COLLIDER,
                        net.minecraft.world.level.ClipContext.Fluid.NONE, this));
        if (hit.getType() == net.minecraft.world.phys.HitResult.Type.MISS) {
            return 99;
        }
        double floor = hit.getLocation().y;
        double y = from.y;
        double vy = getDeltaMovement().y;
        for (int n = 1; n <= 60; n++) {
            y += vy;
            if (y <= floor) {
                return n;
            }
            vy = (vy - 0.08D) * 0.98D;
        }
        return 99;
    }
