                    Vec3 fwd = getViewVector(1.0F);
                    Vec3 side = new Vec3(-fwd.z, 0.0D, fwd.x);
                    double step = (attackTicks - 20) / 2.0D;
                    // the same arithmetic the lanes are laid out with, so the
                    // wedge arrives WITH the wave instead of ahead of it
