                //      that starts from a run reads as travel rather than as
                //      a decision to leave the ground.
                if (attackTicks <= 12) {
                    setDeltaMovement(0.0D, getDeltaMovement().y, 0.0D);
                    if (attackTicks == 2) {
                        playSound(FFSounds.VELKHAR_STEP.get(), 3.0F, 0.6F);
                    }
                    if (attackTicks % 3 == 0) {
                        serverLevel.sendParticles(FFParticles.BLIZZARD_FLAKE.get(),
                                getX(), getY() + 0.1D, getZ(), 8, 0.9D, 0.1D, 0.9D, 0.02D);
                    }
                }

                // ---- 13: THE LEAP. Straight up and slightly onto the player,
                //      so the top of the arc is over the fight rather than over
                //      wherever he happened to be standing.
                if (attackTicks == 13) {
                    Vec3 to = target.position().subtract(position());
                    Vec3 flat = new Vec3(to.x, 0.0D, to.z);
                    if (flat.lengthSqr() > 1.0E-4D) {
                        flat = flat.normalize().scale(Math.min(0.42D, flat.length() * 0.05D));
                    }
                    // MUCH HIGHER. At 1.28 he barely cleared his own height,
                    // so an attack whose whole idea is that it opens from above
                    // was happening at eye level. The hang is the telegraph and
                    // the telegraph has to be over the fight, not in it.
                    setDeltaMovement(flat.x, 2.15D, flat.z);
                    hasImpulse = true;
                    playSound(FFSounds.VELKHAR_SWING.get(), 3.4F, 0.75F);
                    thump(0.4F);
                    floorBurst(serverLevel, position(), 2.4D);
                }

                // ---- 18-34: the hover. Gravity off so the top of the arc is a
                //      HOLD rather than an instant - the pause is the telegraph,
                //      and a telegraph the player cannot see the top of is not
                //      one. He turns to face them throughout.
                if (attackTicks >= 22 && attackTicks <= 34) {
                    setNoGravity(true);
                    Vec3 now = getDeltaMovement();
                    setDeltaMovement(now.x * 0.55D, Math.max(-0.02D, now.y * 0.25D),
                                     now.z * 0.55D);
                    faceChainTarget(target);
                    if (attackTicks % 2 == 0) {
                        serverLevel.sendParticles(FFParticles.SOUL_FROST.get(),
                                getX(), getY() + 1.4D, getZ(), 4, 0.8D, 0.9D, 0.8D, 0.02D);
                    }
                }
                // AT THE TOP OF THE ARC HE SPEAKS - and he never did.
